create function pg_temp.check_it(ok boolean,label text)returns void language plpgsql as $$begin
 if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice'PASS: %',label;end$$;
create function pg_temp.change_pin(request uuid default'11111111-1111-4111-8111-111111111111',
 revision timestamptz default'2026-10-29T00:00:00Z',lat numeric default 33.71,lng numeric default 73.11,confirmed boolean default true)
returns jsonb language sql as $$select public.final_delivery_change_destination(3180,request,revision,lat,lng,'new synthetic pin',confirmed)$$;
set local role anon;
do $$begin perform public.final_delivery_destination_context(3180);raise exception'Anonymous access unexpectedly allowed';
 exception when insufficient_privilege then raise notice'PASS: anonymous context denied';end$$;
set local role service_role;
do $$begin perform pg_temp.change_pin();raise exception'Service impersonation unexpectedly allowed';
 exception when insufficient_privilege then raise notice'PASS: service role cannot impersonate the Customer';end$$;
set local role authenticated;
do $$begin perform 1 from final_delivery_private.destination_amendments;raise exception'Private history exposed';
 exception when insufficient_privilege then raise notice'PASS: private coordinate history inaccessible';end$$;
select pg_temp.check_it((public.final_delivery_destination_context(3180)->>'can_change')::boolean,'owned paused COD context eligible');
select set_config('test.actor','160',true);
select pg_temp.check_it(public.final_delivery_destination_context(3180)='{"code":"FORBIDDEN"}'::jsonb,'other Customer gets no location');
select pg_temp.check_it(pg_temp.change_pin()->>'code'='FORBIDDEN','other Customer update denied');
select set_config('test.actor','999',true),set_config('test.role','rider',true);
select pg_temp.check_it(pg_temp.change_pin()->>'code'='FORBIDDEN','assigned Rider cannot choose Customer destination');
select set_config('test.actor','161',true),set_config('test.role','admin',true);
select pg_temp.check_it(pg_temp.change_pin()->>'code'='FORBIDDEN','Admin cannot bypass Customer confirmation');
select set_config('test.actor','159',true),set_config('test.role','customer',true),set_config('test.allowed','false',true);
select pg_temp.check_it(pg_temp.change_pin()->>'code'='FORBIDDEN','revoked or blocked account denied');
select set_config('test.allowed','true',true);
select pg_temp.check_it(pg_temp.change_pin(confirmed=>false)->>'code'='INVALID_DESTINATION','explicit point confirmation mandatory');
select pg_temp.check_it(pg_temp.change_pin(lat=>'NaN'::numeric)->>'code'='INVALID_DESTINATION','NaN coordinate rejected');
select pg_temp.check_it(pg_temp.change_pin(lng=>181)->>'code'='INVALID_DESTINATION','out of range coordinate rejected');
select pg_temp.check_it(pg_temp.change_pin(revision=>'2026-10-28')->>'code'='DESTINATION_CHANGED','stale revision cannot overwrite destination');
do $$begin update public.orders set delivery_lat=34 where id=3180;raise exception'Direct destination update unexpectedly allowed';
 exception when insufficient_privilege then raise notice'PASS: ordinary direct writes remain locked';end$$;
set local role postgres;
do $$begin update public.orders set delivery_lat=34 where id=3180;raise exception'Unaudited owner update unexpectedly allowed';
 exception when insufficient_privilege then raise notice'PASS: unaudited privileged destination write remains locked';end$$;
update public.riders set is_online=true;
select pg_temp.check_it(pg_temp.change_pin()->>'code'='RIDER_MUST_PAUSE','online Rider prevents destination change');
update public.riders set is_online=false;
insert into fr13_private.sessions values(3180);
select pg_temp.check_it(pg_temp.change_pin()->>'code'='RIDER_MUST_PAUSE','live tracking session prevents destination change');
delete from fr13_private.sessions;
insert into public.delivery_otps values(3180,'ACCEPTED',clock_timestamp()+interval'10 minutes',0,clock_timestamp());
select pg_temp.check_it(pg_temp.change_pin()->>'code'='OTP_ACTIVE','unexpired OTP prevents amendment');
update public.delivery_otps set state='UNKNOWN',expires_at=clock_timestamp()-interval'1 minute';
select pg_temp.check_it(pg_temp.change_pin()->>'code'='OTP_ACTIVE','uncertain send prevents amendment even with an old timestamp');
update public.delivery_otps set state='ACCEPTED',expires_at=clock_timestamp()-interval'1 minute';
insert into public.delivery_proof values('3180');
select pg_temp.check_it(pg_temp.change_pin()->>'code'='HANDOVER_STARTED','existing proof prevents amendment');
delete from public.delivery_proof;
insert into final2_private.photos values(3180,true,'delivery');
select pg_temp.check_it(pg_temp.change_pin()->>'code'='HANDOVER_STARTED','uploaded delivery photo prevents amendment');
update final2_private.photos set uploaded=false;
select pg_temp.check_it(pg_temp.change_pin()->>'code'='HANDOVER_STARTED','in-flight proof reservation prevents amendment');
delete from final2_private.photos;
insert into public.cod_cash_events values(3180);
select pg_temp.check_it(pg_temp.change_pin()->>'code'='HANDOVER_STARTED','cash record prevents amendment');
delete from public.cod_cash_events;
insert into final_delivery_private.rider_earnings values(3180,113);
select pg_temp.check_it(pg_temp.change_pin()->>'code'='HANDOVER_STARTED','earned fee prevents amendment');
delete from final_delivery_private.rider_earnings;
update public.payments set status='completed';
select pg_temp.check_it(pg_temp.change_pin()->>'code'='HANDOVER_STARTED','settled payment prevents amendment');
update public.payments set status='pending';
update public.orders set otp_admin_review=true where id=3180;
select pg_temp.check_it(pg_temp.change_pin()->>'code'='HANDOVER_STARTED','OTP review flag cannot be bypassed');
update public.orders set otp_admin_review=false,order_status='delivered'where id=3180;
select pg_temp.check_it(pg_temp.change_pin()->>'code'='WRONG_STATE','delivered order cannot change destination');
update public.orders set order_status='on_the_way'where id=3180;
update public.orders set user_id=159 where id=3181;
select pg_temp.check_it(public.final_delivery_destination_context(3181)='{"code":"FORBIDDEN"}'::jsonb,'even another owned order is outside the approved TEST scope');
select pg_temp.check_it(public.final_delivery_change_destination(3181,'44444444-4444-4444-8444-444444444444','2026-10-29',34,74,'synthetic',true)->>'code'='FORBIDDEN','correction RPC cannot mutate any other owned order');
update public.orders set user_id=160 where id=3181;
set local role authenticated;
select pg_temp.check_it(pg_temp.change_pin()->>'code'='OK','owning Customer confirms actual destination through trusted RPC');
select pg_temp.check_it(pg_temp.change_pin()->>'replayed'='true','identical uncertain request replays without another write');
select pg_temp.check_it(pg_temp.change_pin(lat=>34)->>'code'='REQUEST_CONFLICT','request UUID cannot be reused with different coordinates');
select pg_temp.check_it(pg_temp.change_pin(request=>'22222222-2222-4222-8222-222222222222')->>'code'='DESTINATION_CHANGED','concurrent old revision rejected after first amendment');
do $$begin update public.orders set delivery_lat=34 where id=3180;raise exception'Old audit reused';
 exception when insufficient_privilege then raise notice'PASS: prior audit cannot authorize a different later tuple';end$$;
set local role postgres;
select pg_temp.check_it((select delivery_lat=33.71 and delivery_lng=73.11 and order_status='on_the_way'and amount=470 and fare=120 and rider_id=999 and user_id=159 from public.orders where id=3180),'status assignment and original charges unchanged');
select pg_temp.check_it((select quote='{"expected_amount":113}'::jsonb from final_delivery_private.pay_snapshots where order_id=3180),'frozen Rider pay unchanged');
select pg_temp.check_it((select stock_qty=29 from public.products where id=224),'inventory unchanged');
select pg_temp.check_it(not exists(select 1 from public.delivery_route_cache where order_id=3180),'obsolete route geometry removed');
select pg_temp.check_it(exists(select 1 from fr14_private.attempts where order_id=3180 and token='synthetic-quota-lease'),'in-flight quota lease retained for proper settlement');
select pg_temp.check_it((select count(*)=1 and min(state)='INVALIDATED'and min(attempts)=0 from public.delivery_otps where order_id=3180),'expired OTP invalidated without resetting send history or attempt count');
select pg_temp.check_it((select count(*)=1 and min(customer_id)=159 and min(old_lat)=33.7 and min(new_lat)=33.71 from final_delivery_private.destination_amendments where order_id=3180),'exactly one private audit retains old and new point');
select pg_temp.check_it((select count(*)=1 from public.security_audit_log where action='delivery_destination_changed'and actor_id=159 and target_id=3180),'critical destination change audit recorded once');
select pg_temp.check_it((select delivery_lat=33.7 and delivery_lng=73.1 from public.orders where id=3181),'unrelated order untouched');
select pg_temp.check_it(pg_temp.change_pin(request=>'33333333-3333-4333-8333-333333333333',revision=>(select destination_confirmed_at from public.orders where id=3180))->>'code'='NO_CHANGE','identical destination does not add audit history');
